function ownerName(id){return owners[id]||id}
function company(id){return model.companies.find(c=>c.id===id)}
function loanDebt(id){return model.loans.filter(l=>l.borrower===id).reduce((a,l)=>a+l.balance,0)}
function companyNAV(id,seen=new Set()){if(seen.has(id))throw Error('Circular company ownership');const c=company(id);if(!c)return 0;if(!c.controlled)return c.marketPrice*c.shares;const next=new Set(seen);next.add(id);return model.positions.filter(p=>p.owner===id).reduce((a,p)=>a+positionValue(p,next),0)-loanDebt(id)}
