function lookThrough(id='household',weight=1,path=[],seen=new Set()){if(seen.has(id))throw Error('Circular structure');const next=new Set(seen);next.add(id);let rows=[];for(const p of children(id)){if(p.company&&company(p.company).controlled){const w=weight*p.qty/company(p.company).shares;rows.push(...lookThrough(p.company,w,[...path,p.name],next))}else rows.push({...p,weight,path,value:positionValue(p)*weight})}return rows}
function lookThroughWealth(){function attributableDebt(id,weight=1,seen=new Set()){if(seen.has(id))throw Error('Circular structure');const next=new Set(seen);next.add(id);return (id==='household'?0:loanDebt(id)*weight)+children(id).filter(p=>p.company&&company(p.company).controlled).reduce((a,p)=>a+attributableDebt(p.company,weight*p.qty/company(p.company).shares,next),0)}return lookThrough().reduce((a,p)=>a+p.value,0)-attributableDebt('household')+model.loans.reduce((a,l)=>a+l.balance,0)}
