function holdingRows(){let rows=holdingMode==='lookthrough'?lookThrough():holdingMode==='personal'?children('household'):model.positions.map(p=>({...p,value:positionValue(p)}));return rows.filter(p=>(holdingTab==='All'||(holdingTab==='ISAs'?p.wrapper==='ISA':p.type===holdingTab))&&(ownerFilter==='All'||p.owner===ownerFilter)&&(wrapperFilter==='All'||p.wrapper===wrapperFilter)&&[p.name,p.code,ownerName(p.owner)].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(sortDesc?-1:1)*((a.value??positionValue(a))-(b.value??positionValue(b))))}
