function holdingDetail(id){const p=model.positions.find(p=>p.id===id),c=p.company&&company(p.company);modal(`<div class="modaleyebrow">HOLDING / ${esc(ownerName(p.owner))}</div><h2>${esc(p.name)}</h2><p>${esc(p.code)}</p><div class="modal-wealth">${gbp(positionValue(p))}</div>${[['Quantity',num(p.qty)],['Price per unit',gbp(positionPrice(p),2)],['Cost basis · total',gbp(p.cost)],['Estimated annual cash yield',num(p.yield)+'%'],['Unrealised change',gbp(positionValue(p)-p.cost)],['Wrapper',p.wrapper],['Valuation date',date(p.asof)],['Tax classification',p.tax]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}${c?`<p class="note">${c.controlled?'Price follows company net assets ÷ issued shares. Underlying assets replace this shareholding in look-through wealth.':'Current price is the recorded reference price, not a live quote. A private-company holding may require a holding-specific valuation.'}</p><button data-open-company="${c.id}">View company & valuations →</button>`:`<p class="note">A price change is an unrealised change, not a completed CGT event. A disposal needs its own dated proceeds, cost and tax treatment. ${p.wrapper==='ISA'?'ISA income and gains are sheltered.':'Confirm instrument-specific income and disposal treatment with your adviser.'}</p>`}<div class="modalactions"><button class="primary" data-edit-holding="${p.id}">Edit holding</button></div>`);bindModal()}
function holdingForm(id){const existing=model.positions.find(p=>p.id===id),p=existing||{name:'',code:'',owner:'household',type:'Shares',wrapper:'General account',qty:0,price:0,cost:0,yield:0,asof:today},derived=!!p.company;modal(`<div class="modaleyebrow">HOLDING RECORD</div><h2>${existing?'Edit holding':'Add a holding'}</h2><form id="holding-form"><div class="formgrid"><label class="full">Name<input name="name" required value="${esc(p.name)}"></label><label class="full">Account / description<input name="code" required value="${esc(p.code)}"></label><label>Legal owner<select name="owner">${Object.entries(owners).map(([v,l])=>`<option value="${v}" ${v===p.owner?'selected':''}>${l}</option>`).join('')}</select></label><label>Asset type<select name="type" ${derived?'disabled':''}>${['ETF','Shares','Bonds','Cash','Property'].concat(derived?['Company']:[]).map(v=>`<option ${v===p.type?'selected':''}>${v}</option>`).join('')}</select></label><label>Wrapper<select name="wrapper">${['General account','ISA','Corporate','Personal savings'].map(v=>`<option ${v===p.wrapper?'selected':''}>${v}</option>`).join('')}</select></label><label>Quantity / units<input name="qty" type="number" min="0" step="any" required value="${p.qty}"></label><label>Price per unit · GBP<input name="price" type="number" min="0" step="any" required value="${positionPrice(p)}" ${derived?'disabled':''}></label><label>Total acquisition cost · GBP<input name="cost" type="number" min="0" step="any" required value="${p.cost}"></label><label>Estimated annual cash yield · %<input name="yield" type="number" min="0" max="100" step="any" required value="${p.yield}"></label><label>Price as at<input name="asof" type="date" required value="${p.asof}"></label></div>${derived?'<p>Share price is derived from the company record. Update its valuation or underlying assets in Companies.</p>':''}<p>GBP only in this demo. Updating a valuation is not a buy, sale or tax disposal.</p><div class="error" id="holding-error"></div><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save holding</button></div></form>`);bindModal();$('#holding-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),updated={...p,name:f.get('name').trim(),code:f.get('code').trim(),owner:f.get('owner'),wrapper:f.get('wrapper'),type:derived?p.type:f.get('type'),qty:+f.get('qty'),price:derived?p.price:+f.get('price'),cost:+f.get('cost'),yield:+f.get('yield'),asof:f.get('asof'),tax:p.tax||'Adviser classification required',id:p.id||'h'+Date.now()};if(!updated.name||!updated.code)return;if(updated.type==='Cash'&&updated.price!==1){$('#holding-error').textContent='Cash is recorded in GBP units at £1 per unit.';return}if(updated.wrapper==='ISA'&&updated.owner!=='household'){$('#holding-error').textContent='An ISA must belong to an individual. Choose Personal or another wrapper.';return}if(derived&&updated.qty>company(p.company).shares){$('#holding-error').textContent='Quantity cannot exceed total issued shares.';return}const previous=model.positions;if(existing)model.positions=model.positions.map(h=>h.id===id?updated:h);else model.positions.push(updated);try{rootWealth()}catch{model.positions=previous;$('#holding-error').textContent='This ownership change would create a circular structure.';return}save();closeModal();render();toast('Holding saved. Valuations recalculated.')}}
function cashflow(){let list=cashTab==='Past'?model.payments.filter(p=>p.date<today||['Paid','Received'].includes(p.status)).sort((a,b)=>b.date.localeCompare(a.date)):upcoming();const next=list.filter(p=>!paymentIsInternal(p)&&owners[p.to]&&p.date<= '2026-11-16').reduce((a,p)=>a+p.amount,0);return `${summary(cashTab==='Upcoming'?[[gbp(next),'expected external receipts · next 30 days'],[String(list.filter(p=>p.status==='Estimate').length),'estimates'],[String(list.filter(p=>p.status==='Proposed').length),'proposals']]:[[String(list.length),'historical payments'],['GBP','transaction currency']])}<div class="tabs"><button data-cash-tab="Upcoming" class="${cashTab==='Upcoming'?'selected':''}">Upcoming</button><button data-cash-tab="Past" class="${cashTab==='Past'?'selected':''}">Past payments</button></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Payment</th><th>From → to</th><th>Certainty / status</th><th class="num">Amount</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${date(p.date)}</td><td class="name">${esc(p.name)}<small>${p.type}${paymentIsInternal(p)?' · internal transfer':''}</small></td><td>${esc(ownerName(p.from))} → ${esc(ownerName(p.to))}</td><td>${badge(p.status)}</td><td class="num smallmoney main-number">${gbp(p.amount,2)}</td><td><button class="textbutton" data-payment="${p.id}">Details ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No payments in this view.</td></tr>'}</tbody></table></div><p class="note">Confirmed means an amount and due date are supported; it does not guarantee collection. Estimates can change. Proposed transactions require review and have not been executed. Internal transfers do not create new household wealth.</p>`}
function paymentDetail(id){const p=model.payments.find(p=>p.id===id);modal(`<div class="modaleyebrow">PAYMENT / ${esc(p.status)}</div><h2>${esc(p.name)}</h2><div class="modal-wealth">${gbp(p.amount,2)}</div>${[['Date',date(p.date)],['From',ownerName(p.from)],['To',ownerName(p.to)],['Type',p.type]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}<p class="note">${esc(p.note)}</p>${p.status==='Proposed'?'<p>This local schedule is a planning record. A professional must review it before a real bank or broker instruction.</p>':''}`)}
function scheduleForm(){modal(`<div class="modaleyebrow">CASH FLOW</div><h2>Schedule a transaction</h2><p>Add a proposed movement to the ledger. Nothing will be sent to a bank or broker.</p><form id="schedule-form"><div class="formgrid"><label class="full">Description<input name="name" required placeholder="e.g. November loan repayment"></label><label>Type<select name="type"><option>Loan repayment</option><option>Investment</option><option>Dividend to shareholder</option><option>Income</option><option>Transfer</option></select></label><label>Planned date<input name="date" type="date" required min="${today}" value="2026-11-16"></label><label>From<select name="from">${Object.entries(owners).map(([v,l])=>`<option value="${v}" ${v==='fic'?'selected':''}>${l}</option>`).join('')}<option value="External">External payer</option></select></label><label>To<select name="to">${Object.entries(owners).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}<option value="Broker">Broker / external investment</option></select></label><label>Amount · GBP<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="full">Notes<input name="note" placeholder="Account, creditor or evidence to check"></label></div><div class="error" id="schedule-error"></div><div class="modalactions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Add proposed transaction</button></div></form>`);bindModal();$('#schedule-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.from===d.to){$('#schedule-error').textContent='Choose different source and destination accounts.';return}if(d.type==='Loan repayment'&&(!company(d.from)?.controlled||d.to!=='household'||+d.amount>loanDebt(d.from))){$('#schedule-error').textContent='Choose a company borrower → Personal and an amount within that company’s outstanding loan principal.';return}if(d.type==='Dividend to shareholder'&&d.from==='household'){$('#schedule-error').textContent='A company dividend must originate from a company.';return}model.payments.push({...d,id:'pay'+Date.now(),amount:+d.amount,status:'Proposed',note:d.note||'Liquidity, tax treatment and professional approval to confirm.'});save();cashTab='Upcoming';closeModal();go('cashflow');toast('Proposed transaction added. No payment made.')}}
function ownershipText(c){return model.positions.filter(p=>p.company===c.id).map(p=>ownerName(p.owner)+' · '+num(p.qty/c.shares*100)+'%').join('; ')||'No holding recorded'}
function structureBranch(id='household',seen=new Set()){if(seen.has(id))return '';const next=new Set(seen);next.add(id);return children(id).filter(p=>p.company).map(p=>`<div class="branch">${num(p.qty)} shares · ${num(p.qty/company(p.company).shares*100)}% of ${esc(p.name)}<small>${gbp(positionValue(p))} holding value</small>${company(p.company).controlled?structureBranch(p.company,next):''}</div>`).join('')}
function companies(){if(companySelected)return companyPage(companySelected);const direct=model.positions.filter(p=>p.owner==='household'&&p.company),nested=model.positions.filter(p=>p.owner!=='household'&&p.company),total=direct.reduce((a,p)=>a+positionValue(p),0);return `<div class="page-focus"><div class="focus-label">Current value of your company shares</div><div class="focus-value">${gbp(total)}</div><p>Across ${direct.length} personally held stakes. Company debts are already reflected in the share values.</p></div><section class="company-list">${sectionhead('Held personally')}<div class="company-list-labels"><span>Company and your ownership</span><span>Your stake value</span></div>${direct.map(p=>{const c=company(p.company);return `<div class="company-entry"><div><h3>${esc(c.name)}</h3><p>${num(p.qty/c.shares*100)}% owned · ${num(p.qty)} ordinary shares</p><small>${esc(c.kind)}</small></div><div class="company-stake"><strong>${gbp(positionValue(p))}</strong><span>${c.controlled?'Net-asset estimate':'Reference share price'}</span></div><button data-company="${c.id}">View company →</button></div>`}).join('')||'<p class="note">No personally held company shares recorded.</p>'}</section>${nested.length?`<details class="nested-companies"><summary>Held inside your companies <span>${nested.length} ${nested.length===1?'stake':'stakes'}</span></summary><p>These shareholdings are already included in their parent companies’ assets.</p>${nested.map(p=>`<div class="company-entry"><div><h3>${esc(p.name)}</h3><p>Held by ${esc(ownerName(p.owner))} · ${num(p.qty/company(p.company).shares*100)}% ownership</p></div><div class="company-stake"><strong>${gbp(positionValue(p))}</strong><span>Included in the parent’s assets</span></div><button data-company="${p.company}">View company →</button></div>`).join('')}</details>`:''}<details class="plain-disclosure"><summary>How the ownership fits together</summary><div class="structure">Household${structureBranch()}<div class="branch">Shareholder loan receivables<small>${gbp(model.loans.reduce((a,l)=>a+l.balance,0))} · tracked separately in Capital</small></div></div><p class="note">Parent shares and the assets underneath them represent the same capital. The overview counts each once. Tax valuation records are available within each company.</p></details>`}
function companyPage(id){const c=company(id),owned=model.positions.filter(p=>p.company===id),assets=children(id),nav=companyNAV(id),tax=c.tax,held=owned.reduce((a,p)=>a+p.qty,0),stake=owned.reduce((a,p)=>a+positionValue(p),0),holderNames=[...new Set(owned.map(p=>ownerName(p.owner)))].join(' + '),personal=owned.some(p=>p.owner==='household');return `<button class="textbutton back-link" id="allcompanies">← All companies</button><div class="page-focus"><div class="focus-label">${personal?'Value of your shareholding':'Value held by '+esc(holderNames)}</div><div class="focus-value">${gbp(stake)}</div><p>${num(held)} ordinary shares · ${num(held/c.shares*100)}% ownership · ${gbp(nav/c.shares,2)} per share</p><small>${personal?'Shareholder loan receivables are tracked separately in Capital.':'This stake is included in its parent’s assets and counted once in household wealth.'}</small></div><section class="section value-section">${sectionhead(c.controlled?'How the company’s equity is calculated':'How your shareholding is valued')}<div class="value-equation">${c.controlled?`<div><strong>${gbp(grossAssets(id))}</strong><span>Company assets</span></div><i>−</i><div><strong>${gbp(loanDebt(id))}</strong><span>Shareholder loan debts</span></div><i>=</i><div class="result"><strong>${gbp(nav)}</strong><span>Company equity</span></div>`:`<div><strong>${gbp(c.marketPrice,2)}</strong><span>Reference price per share</span></div><i>×</i><div><strong>${num(held)}</strong><span>Shares held</span></div><i>=</i><div class="result"><strong>${gbp(stake)}</strong><span>Your stake value</span></div>`}</div><p class="note">${c.controlled?'Your stake is the share of this equity that you own. The estimate excludes any external liabilities or tax adjustments not recorded in this demo.':'This uses the recorded company reference price. A minority holding may need its own valuation for a disposal or transfer.'}</p>${!c.controlled?`<button data-price-company="${id}">Update reference price</button>`:''}</section>${assets.length?`<section class="section">${sectionhead('What the company owns',`<span>${assets.length} holdings</span>`)}<div class="tablewrap"><table><thead><tr><th>Holding</th><th class="num">Quantity</th><th class="num">Price per unit</th><th class="num">Current value</th></tr></thead><tbody>${assets.map(p=>`<tr><td><button class="inlinebtn" data-holding="${p.id}">${esc(p.name)} ↗</button><small>${p.type}${p.company?' · included once in the total':''}</small></td><td class="num secondary-number">${num(p.qty)}</td><td class="num secondary-number">${gbp(positionPrice(p),2)}</td><td class="num main-number">${gbp(positionValue(p))}</td></tr>`).join('')}</tbody></table></div></section>`:''}<details class="plain-disclosure"><summary>Tax valuation record <span>For a specific date and purpose</span></summary><p class="note">This record is separate from the current portfolio estimate. A historical HMRC agreement applies only to its stated purpose and conditions.</p><div class="valuation-facts">${[['Tax reference price / share',tax.purpose==='Not yet valued'?'Not recorded':gbp(tax.price,2)],['Valuation date',date(tax.date)],['Basis',tax.basis],['Purpose',tax.purpose],['Reference value of this holding',tax.purpose==='Not yet valued'?'Not recorded':gbp(held*tax.price)]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}</div><p class="note">${esc(tax.ref)}. Share classes, restrictions and control can affect the valuation of a particular holding.</p><button data-valuation="${id}">Edit tax valuation record</button></details>${owned.length>1?`<details class="plain-disclosure"><summary>Ownership breakdown</summary>${owned.map(p=>`<div class="detailrow"><span>${esc(ownerName(p.owner))} · ${num(p.qty)} shares</span><b>${gbp(positionValue(p))}</b></div>`).join('')}</details>`:''}`}
function valuationForm(id){const c=company(id),t=c.tax;modal(`<div class="modaleyebrow">${esc(c.name)} / TAX REFERENCE</div><h2>Record a share valuation</h2><p>Keep the date, purpose and evidence with the price. This does not alter the net-asset estimate or represent a new HMRC agreement.</p><form id="valuation-form"><div class="formgrid"><label>Price per share · GBP<input type="number" name="price" min="0" step="0.0001" required value="${t.price}"></label><label>Valuation date<input type="date" name="date" required value="${t.date}"></label><label>Basis<select name="basis">${['Adviser estimate','Independent valuation','HMRC agreed · sample'].map(v=>`<option ${t.basis===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Purpose<input name="purpose" required value="${esc(t.purpose)}"></label><label class="full">Evidence / agreement reference<input name="ref" required value="${esc(t.ref)}"></label></div><label class="checkbox"><input type="checkbox" required><span>I am recording an illustrative valuation and have identified the purpose and supporting reference. This does not constitute an HMRC approval.</span></label><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save valuation record</button></div></form>`);bindModal();$('#valuation-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));c.tax={...d,price:+d.price};model.valuationHistory.push({company:id,...c.tax,recorded:new Date().toISOString()});save();closeModal();render();toast('Tax valuation recorded separately from portfolio value.')}}
function companyPriceForm(id){const c=company(id);modal(`<div class="modaleyebrow">COMPANY REFERENCE</div><h2>${esc(c.name)}</h2><form id="company-price-form"><div class="formgrid"><label>Current price per share · GBP<input name="price" type="number" min="0" step="0.0001" required value="${c.marketPrice}"></label><label>Price as at<input name="asof" type="date" required value="${today}"></label><label class="full">Price source / evidence<input name="source" required placeholder="e.g. last funding round · reference"></label></div><p>Changes your existing shareholding value and option scenarios. This is not a tax disposal or an HMRC valuation.</p><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary">Save reference price</button></div></form>`);bindModal();$('#company-price-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));c.marketPrice=+d.price;c.source=d.source;model.positions.filter(p=>p.company===id).forEach(p=>p.asof=d.asof);save();closeModal();render();toast('Company price updated across holdings and option scenarios.')}}
function capital(){const debt=model.loans.reduce((a,l)=>a+l.balance,0),cash=children('fic').filter(p=>p.type==='Cash').reduce((a,p)=>a+positionValue(p),0);return `${summary([[gbp(debt),'owed to shareholders'],['0%','interest on both accounts'],[gbp(companyNAV('fic')),'2LR Investments net equity']])}${sectionhead('Shareholder loans','Company owes you · creditor balances')}<div class="tablewrap"><table><thead><tr><th>Creditor</th><th>Borrower</th><th class="num">Current balance</th><th>Rate</th><th></th></tr></thead><tbody>${model.loans.map(l=>`<tr><td class="name">${l.creditor}</td><td>${ownerName(l.borrower)}</td><td class="num smallmoney main-number">${gbp(l.balance)}</td><td>${l.rate}%</td><td><button class="textbutton" data-loan="${l.id}">Schedule ↗</button></td></tr>`).join('')}</tbody></table></div><section class="section">${sectionhead('Plan 2LR Investments’ next receipts')}<div class="twocol"><div><p class="loanline">Illustrative receipts: £14,000. Provisional company tax reserve: £1,000. Allocate the remaining £13,000 between retaining capital and repaying existing principal.</p><div class="row" style="margin-top:20px"><span>To loan repayments</span><b id="allocation-percent">${model.allocation}%</b></div><input class="allocation" type="range" id="allocation" aria-label="Percentage for loan repayment" min="0" max="100" value="${model.allocation}"><div class="row"><small>Retain for reinvestment</small><small>Return principal</small></div></div><div id="capital-results">${capitalResults()}</div></div><button class="primary" id="save-capital-plan" style="margin-top:23px">Save repayment proposal</button><p class="note">Company cash currently ${gbp(cash)}. Preserve sufficient liquidity and reserve actual tax liabilities before repayment. Principal repayments reduce the creditor account; they are not deductible business expenses or personal dividends. Paying a new dividend is a different action, requiring distributable profits and personal income-tax review.</p></section><section class="section">${sectionhead('Equity capital')}<div class="detailrow"><span>Household → 2LR Investments</span><b>1,000 ordinary shares · ${gbp(companyNAV('fic'))} net-asset estimate</b></div><p class="note">Loans and share capital are different claims. The company can repay a genuine creditor balance, subject to its obligations and liquidity; extracting equity or profits needs its own legal and tax treatment.</p></section>`}
function capitalResults(){const repay=13000*model.allocation/100;return [['Tax cash reserve',1000],['Proposed principal repayments',repay],['Retained for company investment',13000-repay],['Will’s share of the repayments',repay*.875]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${gbp(b,2)}</b></div>`).join('')}
function loanSchedule(id){const l=model.loans.find(l=>l.id===id),share=l.balance/loanDebt(l.borrower),plans=upcoming().filter(p=>p.type==='Loan repayment'&&p.from===l.borrower);let balance=l.balance;modal(`<div class="modaleyebrow">LOAN ACCOUNT / 0% INTEREST</div><h2>${l.creditor}</h2><p>${ownerName(l.borrower)} owes ${gbp(l.balance)}. Proposed repayments below do not alter the current balance.</p><div class="detailrow"><span>Original advance</span><b>${gbp(l.original)}</b></div><div class="detailrow"><span>Principal already repaid</span><b>${gbp(l.original-l.balance)}</b></div><div class="tablewrap" style="margin-top:25px"><table><thead><tr><th>Date</th><th>Status</th><th class="num">Principal</th><th class="num">Balance if paid</th></tr></thead><tbody>${plans.map(p=>{const amount=p.amount*share;balance-=amount;return `<tr><td>${date(p.date)}</td><td>${badge(p.status)}</td><td class="num">${gbp(amount,2)}</td><td class="num">${gbp(balance,2)}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No repayment proposals.</td></tr>'}</tbody></table></div><p class="note">Split in proportion to creditor balances. Review the agreement, creditor consent and company liquidity before any real payment.</p><div class="modalactions"><button class="primary" id="loan-add-payment">Schedule a proposal</button></div>`);$('#loan-add-payment').onclick=scheduleForm}
function allowances(){const a=model.allowances;const rows=[{id:'isa',name:'ISA',limit:20000,used:a.isa,unit:'subscriptions',note:'Personal account · eligibility required',help:'Only personal subscriptions qualify. The company cannot fund an ISA directly. Receive a valid loan repayment or an approved taxable dividend first, then subscribe personally.'},{id:'eis',name:'EIS',limit:1000000,used:a.eis,unit:'standard subscription limit',note:'Capacity is not guaranteed tax relief',help:'30% income-tax relief, limited by tax liability and all scheme conditions. The standard £1m limit can extend to £2m if the excess over £1m is invested in knowledge-intensive companies. Qualifying shares normally need to be held for at least three years. EIS is high risk and illiquid; obtain suitability and eligibility review.'},{id:'cgt',name:'Capital gains',limit:3000,used:a.cgt,unit:'annual exempt amount',note:'Applies to realised gains, not contributions',help:'The £3,000 annual exempt amount is against taxable realised gains, after relevant losses and rules. Unrealised price changes do not consume it. General CGT rates are 18% or 24% depending on the available basic-rate band; relief-specific rules can differ.'},{id:'dividend',name:'Dividend allowance',limit:500,used:a.dividend,unit:'dividend income at nil rate',note:'Dividends still occupy tax bands',help:'Personal dividends above applicable allowances use the dividend rates: 10.75%, 35.75% or 39.35% in 2026/27. A dividend received by the company is different from a dividend the company pays to you.'},{id:'savings',name:'Savings allowance',limit:500,used:a.savings,unit:'higher-rate taxpayer assumption',note:'£1,000 basic · £500 higher · £0 additional',help:'Personal Savings Allowance depends on the individual’s tax band. This demo assumes a higher-rate taxpayer, with £500 fully used. A company has no personal savings allowance.'}];return `<div class="basisbanner"><span>Will · UK resident · 6 April 2026 – 5 April 2027</span><span>Illustrative usage; not calculated from a live tax return.</span></div><div class="tablewrap"><table class="allowance-table"><thead><tr><th>Allowance</th><th class="num">Annual limit</th><th class="num">Used</th><th class="num">Remaining</th><th>Basis</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td class="name">${a.name}<small>${a.unit}</small></td><td class="num">${gbp(a.limit)}</td><td class="num">${gbp(a.used)}</td><td class="num smallmoney main-number">${gbp(Math.max(0,a.limit-a.used))}<div class="bar" style="margin-left:auto"><span style="width:${Math.min(100,a.used/a.limit*100)}%"></span></div></td><td><small>${a.note}</small></td><td><button class="textbutton" data-allowance="${a.id}">Details ↗</button></td></tr>`).join('')}</tbody></table></div><section class="section">${sectionhead('Income thresholds','England / Wales / Northern Ireland bands assumed')}<div class="tablewrap"><table><thead><tr><th>Threshold</th><th class="num">Level</th><th class="num">Illustrative headroom</th><th>Assumption</th></tr></thead><tbody><tr><td>Personal Allowance taper starts</td><td class="num">£100,000</td><td class="num">£25,000</td><td><small>Adjusted net income £75,000</small></td></tr><tr><td>Additional-rate income threshold</td><td class="num">£125,140</td><td class="num">£50,140</td><td><small>Different income types have different rates</small></td></tr></tbody></table></div><p class="note">Assumes £65,000 other income and £10,000 taxable portfolio receipts, with no pension or Gift Aid adjustment. Basic-rate band fully used; £12,570 Personal Allowance assumed. Forecasts are illustrative and must be reconciled before decisions.</p></section><div class="allowance-detail"><h3>Company receipts → personal investment</h3><p>Reserve company tax and liquidity first. A genuine interest-free loan principal repayment can return existing capital; it does not create a new dividend. You can then consider using your personal ISA allowance. EIS needs a separate risk, eligibility and tax-liability review. A new company dividend needs distributable profits and a personal-tax check.</p><button class="textbutton" data-view="capital" style="margin-top:12px">Model a principal repayment →</button></div>${model.proposals.length?`<small>${model.proposals.length} saved capital proposal(s), awaiting review.</small>`:''}`;}
function allowanceDetail(id){const map={isa:['ISA',20000,'Subscriptions shelter future UK income and gains. You must be eligible to subscribe. Corporate cash is not a personal subscription until it has been lawfully paid to you.'],eis:['EIS',1000000,'This is remaining standard subscription capacity, not guaranteed relief. 30% income-tax relief is limited by liability and scheme conditions. Up to £2m may qualify where the excess over £1m is invested in knowledge-intensive companies. Normally hold qualifying shares at least three years. High risk and illiquid.'],cgt:['Capital gains',3000,'The annual exempt amount offsets realised taxable gains, not the value invested. Losses, matching rules, wrappers and disposal type matter. A market price update is not a disposal.'],dividend:['Dividend allowance',500,'A nil-rate allowance; dividend income still uses your income-tax bands. Rates for personal dividends in 2026/27 are 10.75%, 35.75% and 39.35%.'],savings:['Savings allowance',500,'This demo assumes a higher-rate taxpayer. Personal Savings Allowance: £1,000 basic-rate, £500 higher-rate, £0 additional-rate.']},[name,limit,help]=map[id];modal(`<div class="modaleyebrow">PERSONAL / 2026–27</div><h2>${name}</h2><p>${help}</p><form id="allowance-form"><label class="formlabel" style="margin-top:24px">Illustrative amount used · GBP<input name="used" type="number" min="0" max="${id==='eis'?2000000:100000000}" step="0.01" required value="${model.allowances[id]}"></label><p class="note">Usage is manually maintained here. An edit changes headroom only; it does not create a subscription, relief claim or tax filing.</p><div class="modalactions"><button type="button" data-close>Close</button><button class="primary">Update usage</button></div></form>`);bindModal();$('#allowance-form').onsubmit=e=>{e.preventDefault();model.allowances[id]=+new FormData(e.target).get('used');save();closeModal();render();toast('Illustrative allowance usage updated.')}}
function options(){return `${summary([[String(model.options.length),'agreements'],[num(model.options.reduce((a,o)=>a+o.granted,0)),'options granted'],['Excluded','from consolidated wealth']])}<div class="tablewrap"><table><thead><tr><th>Company / agreement</th><th class="num">Vested options</th><th class="num">Exercise price</th><th class="num">Vested exercise cost</th><th>Expiry</th><th></th></tr></thead><tbody>${model.options.map(o=>`<tr><td class="name">${esc(company(o.company).name)}<small>${esc(o.scheme)} · ${esc(o.holder)}</small></td><td class="num">${num(o.vested)}<small>of ${num(o.granted)} granted</small></td><td class="num secondary-number">${gbp(o.strike,2)}</td><td class="num main-number">${gbp(o.vested*o.strike)}</td><td>${date(o.expiry)}</td><td><button class="textbutton" data-option="${o.id}">Agreement ↗</button></td></tr>`).join('')}</tbody></table></div><p class="note">Options are rights to acquire shares. Exercise costs and intrinsic-value scenarios are not option fair values or guaranteed proceeds. Vesting figures are recorded checkpoints; the agreement sets the legal terms.</p><details class="plain-disclosure"><summary>EMI records and eligibility</summary><p class="note">Keep grant-date actual and unrestricted market values, the HMRC valuation reference, vesting, exercise windows and disqualifying events with the agreement. EMI requires a qualifying company, trade, employee and grant. An investment FIC should not be assumed to qualify. An agreed EMI valuation is generally valid for 90 days for a grant, subject to unchanged circumstances.</p><button class="textbutton" data-command="rules">HMRC rules and sources ↗</button></details>`}

function optionDetail(id){const o=model.options.find(o=>o.id===id),c=company(o.company),p=c.marketPrice??companyNAV(c.id)/c.shares;modal(`<div class="modaleyebrow">${esc(o.scheme)} / AGREEMENT RECORD</div><h2>${c.name}</h2><p>${esc(o.agreement)}</p>${[['Holder',o.holder],['Grant date',date(o.grant)],['Options / vested',`${num(o.granted)} / ${num(o.vested)}`],['Exercise price',gbp(o.strike,2)],['Recorded company reference price',gbp(p,2)],['Exercise cost · vested only',gbp(o.vested*o.strike)],['Vested intrinsic scenario · before tax',gbp(Math.max(0,p-o.strike)*o.vested)],['Expiry',date(o.expiry)]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${esc(b)}</b></div>`).join('')}<div class="section"><h3>Vesting terms</h3><p class="note">${esc(o.vesting)}. Recorded vested quantity as at 17 October 2026; confirm with the scheme administrator.</p><h3>Agreement preview · illustrative</h3><p class="note">Optionholder may acquire up to ${num(o.granted)} ordinary shares at ${gbp(o.strike,2)} per share, subject to vesting, leaver provisions, exercise notices and the agreement’s conditions. This summary is not an executed agreement.</p>${o.scheme==='EMI'?`<p class="note">Historical sample grant valuation: AMV ${gbp(o.amv??o.strike,2)} / UMV ${gbp(o.umv??o.strike,2)} per share as at ${date(o.valuationDate||o.grant)} · ${esc(o.valuationRef||'Evidence required')}. Record actual market value, unrestricted market value, restrictions and the original HMRC agreement separately. Tax treatment on exercise and sale needs professional review.</p>`:'<p class="note">Unapproved options may create income tax and, where relevant, NIC liabilities on exercise. No tax outcome is calculated here.</p>'}</div><div class="modalactions"><button id="option-update-vesting">Update vested quantity</button><button class="primary" data-open-company="${c.id}">Company valuation →</button></div>`);bindModal();$('#option-update-vesting').onclick=()=>{modal(`<div class="modaleyebrow">OPTION AGREEMENT</div><h2>Update vesting checkpoint</h2><form id="vest-form"><label class="formlabel">Vested options · maximum ${num(o.granted)}<input name="vested" type="number" min="0" max="${o.granted}" step="1" required value="${o.vested}"></label><label class="formlabel" style="margin-top:16px">Evidence / administrator confirmation<input name="evidence" required placeholder="Checkpoint reference"></label><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary">Save checkpoint</button></div></form>`);bindModal();$('#vest-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));o.vested=+d.vested;o.checkpoint=d.evidence;save();closeModal();render();toast('Vesting checkpoint saved.')}}}
function optionForm(){modal(`<div class="modaleyebrow">OPTION REGISTER</div><h2>Add an agreement</h2><form id="option-form"><div class="formgrid"><label>Issuing company<select name="company">${model.companies.map(c=>`<option value="${c.id}" ${c.id==='northstar'?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Scheme<select name="scheme"><option>EMI</option><option>Unapproved</option><option>CSOP</option></select></label><label>Holder<input name="holder" required value="Will Hackett"></label><label>Grant date<input name="grant" type="date" required value="${today}"></label><label>Options granted<input name="granted" type="number" min="1" step="1" required></label><label>Options vested<input name="vested" type="number" min="0" step="1" value="0" required></label><label>Exercise price · GBP<input name="strike" type="number" min="0" step="0.0001" required></label><label>Expiry<input name="expiry" type="date" required></label><label>Grant-date actual market value / share<input name="amv" type="number" min="0" step="0.0001" required></label><label>Grant-date unrestricted market value / share<input name="umv" type="number" min="0" step="0.0001" required></label><label>Grant valuation date<input name="valuationDate" type="date" required></label><label>Valuation evidence reference<input name="valuationRef" required></label><label class="full">Vesting terms<input name="vesting" required placeholder="Cliff, monthly vesting, performance conditions…"></label><label class="full">Agreement reference<input name="agreement" required placeholder="Document or scheme administrator reference"></label></div><div class="error" id="option-error"></div><p>Records only. Eligibility and tax-advantaged status require professional confirmation.</p><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary">Save agreement</button></div></form>`);bindModal();$('#option-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(+d.vested>+d.granted){$('#option-error').textContent='Vested quantity cannot exceed granted quantity.';return}if(d.expiry<=d.grant){$('#option-error').textContent='Expiry must follow the grant date.';return}if(d.scheme==='EMI'&&company(d.company).controlled){$('#option-error').textContent='The modelled FICs are investment companies. EMI eligibility cannot be assumed; use the qualifying external trading company or record an unapproved agreement.';return}model.options.push({...d,id:'opt'+Date.now(),granted:+d.granted,vested:+d.vested,strike:+d.strike,amv:+d.amv,umv:+d.umv,status:'Granted'});save();closeModal();go('options');toast('Agreement recorded. No options granted or exercised.')}}
function todo(){const f=filings.find(f=>f.id===selectedTask)||filings[0],open=filings.filter(t=>todoStatus(t)!=='Submitted (demo)'),done=filings.filter(t=>todoStatus(t)==='Submitted (demo)');const taskRow=t=>`<button class="task task-wide" data-select-task="${t.id}"><span class="task-date"><span>Due</span>${date(t.due)}</span><span class="task-description"><span class="tasktitle">${t.action}</span><small>${t.entity}</small><span class="task-needed">${model.filings[t.id]?.evidenceReady?'Supporting demo evidence attached':t.ready}</span></span><span class="task-status">${badge(todoStatus(t))}<span>Open draft →</span></span></button>`;if(todoTab==='Archive')return `<div class="tabs"><button data-todo-tab="Tasks">Tasks</button><button class="selected" data-todo-tab="Archive">Evidence & history</button></div>${archive()}`;if(todoStage==='draft')return `<div class="draft-reading"><div class="draft-context">${badge(todoStatus(f))}<span>${todoStatus(f)==='Needs evidence'?'Supporting evidence is still needed. You can read the draft below.':todoStatus(f)==='Approved'?'Review the approved draft before the next step.':'Check the details, then send the draft for professional review.'}</span></div><div class="draft-tools"><button class="textbutton" id="save-draft">Save draft changes</button><button class="textbutton" id="download-draft">Download workpaper ↗</button></div><article class="document"><div class="doclabel">DRAFT WORKPAPER · ${esc(f.entity.toUpperCase())}</div><h2>${f.name}</h2><p>${f.period}</p>${f.fields.map(([a,b])=>`<div class="docrow"><span>${a}</span><b>${b}</b></div>`).join('')}<label><span class="invisible">Draft notes</span><textarea id="draft-notes" aria-label="Draft notes">${esc(model.drafts[f.id]||f.text)}</textarea></label><small>Editable sample workpaper. Not a statutory return or signed accounts.</small></article><section class="doccontrols"><h2>Evidence & next step</h2>${f.evidence.map(e=>`<div class="detailrow"><span>${e}</span><span>${e.startsWith('Missing')&&!model.filings[f.id]?.evidenceReady?'Needed':'Sample available'}</span></div>`).join('')}${f.status==='Needs evidence'&&!model.filings[f.id]?.evidenceReady?'<button class="textbutton" id="sample-evidence" style="margin-top:20px">Use illustrative evidence to continue demo →</button>':''}<p class="note">${f.basis}</p>${todoControls(f)}</section></div>`;return `<div class="tabs"><button class="selected" data-todo-tab="Tasks">Tasks</button><button data-todo-tab="Archive">Evidence & history</button></div><div class="task-list-heading"><h2>${open.length} ${open.length===1?'task needs':'tasks need'} your attention</h2><p>In deadline order. Open a task to see the full draft.</p></div><div class="tasklist spacious-tasks">${open.map(taskRow).join('')||'<p class="note">You’re up to date. No outstanding tasks.</p>'}</div>${done.length?`<details class="plain-disclosure"><summary>Completed in this demo <span>${done.length}</span></summary>${done.map(taskRow).join('')}</details>`:''}`}
function todoControls(f){const status=todoStatus(f),missing=f.status==='Needs evidence'&&!model.filings[f.id]?.evidenceReady;if(status==='Submitted (demo)')return '<div class="read-only">Simulated submission recorded. Nothing was sent to HMRC, Companies House or a bank.</div>';if(missing)return '<small>Complete the evidence above before requesting review.</small>';if(status==='In professional review')return `<label class="formlabel">Reviewer name<input id="reviewer" placeholder="Professional reviewer · demo"></label><label class="checkbox"><input id="attest" type="checkbox"><span>I am simulating professional approval of this draft and its supporting evidence.</span></label><button class="primary" id="approve-draft" disabled>Approve draft · demo</button>`;if(status==='Approved')return `<label class="checkbox"><input id="submit-attest" type="checkbox"><span>Simulate submission only. I understand this does not make a statutory filing or payment.</span></label><button class="primary" id="submit-draft" disabled>${f.id==='ctpay'?'Simulate payment handoff':'Simulate submission'}</button>`;return '<button class="primary" id="review-draft">Send for professional review · demo</button>'}
function archive(){const rows=[['Broker valuation summary','2LR Investments','Sample · 17 Oct 2026','broker'],['Shareholder loan agreements','Two interest-free creditor accounts','Sample · principal only','loans'],['Option agreements','Northstar Labs','Sample · EMI + unapproved','options'],['Tax valuation records','Companies and share prices','Date and purpose attached','values']];return `<div class="tablewrap"><table><thead><tr><th>Evidence</th><th>Scope</th><th>Basis</th><th></th></tr></thead><tbody>${rows.map(([a,b,c,id])=>`<tr><td class="name">${a}</td><td>${b}</td><td>${c}</td><td><button class="textbutton" data-evidence="${id}">Preview ↗</button></td></tr>`).join('')}</tbody></table></div><section class="section">${sectionhead('Review history')}${model.audit.length?model.audit.slice().reverse().map(a=>`<div class="historyitem">${esc(a.item)} · ${esc(a.status)}${a.reviewer?' · '+esc(a.reviewer):''}<small>${new Date(a.time).toLocaleString('en-GB')}</small></div>`).join(''):'<p class="note">No draft approvals or simulated submissions recorded yet.</p>'}</section>`}
function evidence(id){const bodies={broker:`<p>Current illustrative company assets: ${gbp(grossAssets('fic'))}; net equity after loans: ${gbp(companyNAV('fic'))}. This summary includes the property subsidiary shareholding once. Reporting-date evidence must be supplied separately.</p>`,loans:`<p>${model.loans.map(l=>`${l.creditor}: ${gbp(l.balance)} due from ${ownerName(l.borrower)}, interest ${l.rate}%.`).join('<br>')}</p><p>Sample agreement summary only. Principal repayments are not business expenses or dividends.</p>`,options:`<p>${model.options.map(o=>`${esc(company(o.company).name)} · ${esc(o.scheme)} · ${num(o.granted)} options · ${esc(o.agreement)}`).join('<br>')}</p><p>Sample records; signed originals and administrator confirmation required.</p>`,values:`<p>${model.companies.map(c=>`${esc(c.name)}: ${gbp(c.tax.price,2)} per share · ${date(c.tax.date)} · ${esc(c.tax.purpose)} · ${esc(c.tax.basis)}`).join('<br>')}</p><p>Historical or purpose-specific references are not universal market values.</p>`};modal(`<div class="modaleyebrow">EVIDENCE PREVIEW / ILLUSTRATIVE</div><h2>${{broker:'Broker valuation summary',loans:'Loan agreements',options:'Option agreements',values:'Tax valuations'}[id]}</h2>${bodies[id]}`)}
function wealthBridge(){const personal=children('household').reduce((a,p)=>a+positionValue(p),0),loans=model.loans.reduce((a,l)=>a+l.balance,0);modal(`<div class="modaleyebrow">CONSOLIDATED WEALTH</div><h2>Each pound, once.</h2><p>The household balance sheet includes company equity after its debts, plus the loans owed back to the household. You do not add the company’s underlying assets again.</p>${[['Personal legal holdings, including company equity',personal],['Loan receivables from your companies',loans],['Household net wealth',rootWealth()],['Look-through net assets · cross-check',lookThroughWealth()]].map(([a,b])=>`<div class="detailrow"><span>${a}</span><b>${gbp(b)}</b></div>`).join('')}<p class="note">The alternative look-through view replaces controlled company shares with attributable assets, subtracts the corresponding loan liabilities and includes the household’s creditor claims. External-company interests remain at their reference share value. Options and unrecorded external liabilities are excluded from this illustrative snapshot.</p>`)}
function rules(){modal(`<div class="modaleyebrow">BASIS / 17 OCTOBER 2026</div><h2>Assumptions & tax rules</h2><p>GBP-only mock portfolio. UK-resident individuals; England/Wales/NI income bands. Company taxable profits and income classifications require professional approval. No inheritance planning is included.</p><div class="source-list"><a target="_blank" rel="noreferrer" href="https://www.gov.uk/individual-savings-accounts">ISA · £20,000 annual subscription limit ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/guidance/venture-capital-schemes-tax-relief-for-investors">EIS · relief, eligibility and limits ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/capital-gains-tax/allowances">Capital gains · annual exempt amount ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/tax-on-dividends">Personal dividend allowance and rates ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/hmrc-internal-manuals/company-taxation-manual/ctm02060">Corporate dividends · exemption conditions ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/hmrc-internal-manuals/corporate-finance-manual/cfm40130">Corporate funds · loan relationship treatment ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/directors-loans/you-lend-your-company-money">Loans to your company ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/prepare-file-annual-accounts-for-limited-company">Accounts, payment and tax-return deadlines ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/guidance/get-a-share-scheme-valuation-from-hmrc">HMRC share-scheme valuations · date and purpose ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/hmrc-internal-manuals/capital-gains-manual/cg59562">Unquoted shares · holding-specific valuation ↗</a><a target="_blank" rel="noreferrer" href="https://www.gov.uk/tax-employee-share-schemes/enterprise-management-incentives-emis">EMI eligibility and option tax treatment ↗</a></div><p class="note">Loan principal repayments are not deductible. Corporate ordinary dividends may be exempt; fund returns, interest, rent and gains require separate treatment. A close investment-holding company generally uses the 25% main rate without small-profits relief. Cash reserves are provisional, not computed tax liabilities. Demo workflows do not contact any authority, bank, broker or reviewer.</p>`)}
function download(text,name,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function exportHoldings(){const cols=['Name','Owner','Type','Wrapper','Quantity','Price GBP','Market value GBP','Cost basis GBP','Valuation date','Tax classification'];const csv=[cols,...model.positions.map(p=>[p.name,ownerName(p.owner),p.type,p.wrapper,p.qty,positionPrice(p),positionValue(p),p.cost,p.asof,p.tax])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');download(csv,'ron-illustrative-holdings.csv','text/csv');toast('Holdings register exported. Rows include nested company records.')}
function companyForm(){modal(`<div class="modaleyebrow">COMPANY REGISTER</div><h2>Add a company</h2><p>Create an empty record. Then add its assets in Holdings. No capital movement is assumed.</p><form id="company-form"><div class="formgrid"><label class="full">Company name<input name="name" required></label><label>Type<select name="kind"><option>Family investment company</option><option>Investment subsidiary</option><option>External trading company</option></select></label><label>Issued ordinary shares<input type="number" min="1" step="1" name="shares" required value="1000"></label><label>Year end<input name="yearEnd" required value="31 March"></label><label>Owner of the shareholding<select name="owner">${Object.entries(owners).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Number of shares owned<input name="owned" type="number" step="1" min="0" required value="1000"></label><label>Reference price · external company only<input name="marketPrice" type="number" step="0.01" min="0" value="0" required></label></div><div class="error" id="company-error"></div><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary">Add company record</button></div></form>`);bindModal();$('#company-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(+d.owned>+d.shares){$('#company-error').textContent='Owned shares cannot exceed issued shares.';return}const id='co'+Date.now(),controlled=d.kind!=='External trading company';const c={id,name:d.name.trim(),short:d.name.trim(),kind:d.kind,shares:+d.shares,controlled,yearEnd:d.yearEnd,marketPrice:+d.marketPrice,owner:ownerName(d.owner)+' · '+num(+d.owned/+d.shares*100)+'%',tax:{price:0,date:today,basis:'Adviser estimate',purpose:'Not yet valued',ref:'No valuation evidence recorded'}};model.companies.push(c);owners[id]=c.short;model.positions.push({id:'share'+Date.now(),name:c.name,code:'Ordinary company shares',owner:d.owner,type:'Company',wrapper:d.owner==='household'?'General account':'Corporate',qty:+d.owned,price:0,cost:0,yield:0,tax:'Adviser classification required',asof:today,company:id});save();companySelected=id;closeModal();go('companies');toast('Company added. Add its underlying assets in Holdings.')}}

function loanForm(){modal(`<div class="modaleyebrow">CAPITAL / OPENING BALANCE</div><h2>Add a shareholder loan account</h2><p>Record a genuine loan already owed by a company to a household member. No cash is moved.</p><form id="loan-form"><div class="formgrid"><label>Household creditor<input name="creditor" required placeholder="Name of the lender"></label><label>Company borrower<select name="borrower">${model.companies.filter(c=>c.controlled).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Original principal advanced · GBP<input name="original" type="number" min="0.01" step="0.01" required></label><label>Current principal outstanding · GBP<input name="balance" type="number" min="0" step="0.01" required></label><label class="full">Signed agreement / ledger reference<input name="ref" required></label></div><p>Interest rate: 0%. Principal is a balance-sheet liability, not a deductible expense. Amounts are opening records, not new transactions.</p><div class="error" id="loan-error"></div><div class="modalactions"><button type="button" data-close>Cancel</button><button class="primary">Save loan account</button></div></form>`);bindModal();$('#loan-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(+d.balance>+d.original){$('#loan-error').textContent='Outstanding principal cannot exceed the original advance in this simple account. Record additional advances separately.';return}model.loans.push({...d,id:'loan'+Date.now(),original:+d.original,balance:+d.balance,rate:0});save();closeModal();render();toast('Opening creditor balance recorded. No cash moved.')}}

function bindModal(){ $$('[data-close]').forEach(b=>b.onclick=closeModal);$$('[data-edit-holding]').forEach(b=>b.onclick=()=>holdingForm(b.dataset.editHolding));$$('[data-open-company]').forEach(b=>b.onclick=()=>{closeModal();companySelected=b.dataset.openCompany;go('companies')})}
function taskTransition(f,status,reviewer=''){model.filings[f.id]={...model.filings[f.id],status};model.drafts[f.id]=$('#draft-notes').value;model.audit.push({item:f.name,status,reviewer,time:new Date().toISOString()});save();render();toast(status==='Submitted (demo)'?'Simulation saved. Nothing submitted or paid.':'Draft status updated.')}
function render(){for(const c of model.companies)if(c.controlled)owners[c.id]=c.short;const unresolved=filings.filter(f=>todoStatus(f)!=='Submitted (demo)').length;$('#nav').innerHTML=views.map(([v,l])=>`<button data-view="${v}" class="${v===view?'active':''}" ${v===view?'aria-current="page"':''}>${l}${v==='todo'?`<span class="navcount">${unresolved}</span>`:''}</button>`).join('');$('#eyebrow').textContent='2LR PRIVATE OFFICE / '+(view==='allowances'?'2026–27':'17 OCTOBER 2026');$('#title').textContent=metadata[view][0];$('#description').textContent=metadata[view][1];if(view==='todo'&&todoStage==='draft'&&todoTab==='Tasks'){$('#title').textContent=filings.find(f=>f.id===selectedTask).action;$('#description').textContent=filings.find(f=>f.id===selectedTask).entity+' · Due '+date(filings.find(f=>f.id===selectedTask).due)}if(view==='companies'&&companySelected){$('#title').textContent=company(companySelected).name;$('#description').textContent=company(companySelected).kind}$('#actions').innerHTML=({overview:'<button class="primary" data-view="todo">Review next task →</button>',holdings:'<button id="export">Export</button><button class="primary" id="add-holding">Add holding</button>',cashflow:'<button class="primary" id="schedule">Schedule transaction</button>',companies:companySelected?'':'<button class="primary" id="add-company">Add company</button>',capital:'<button id="add-loan">Add loan account</button><button id="schedule">Schedule repayment</button>',allowances:'<button id="tax-rules">Tax rules ↗</button>',options:'<button class="primary" id="add-option">Add agreement</button>',todo:todoStage==='draft'&&todoTab==='Tasks'?'<button id="alltasks">← All tasks</button>':''})[view];$('#content').innerHTML=({overview,holdings,cashflow,companies,capital,allowances,options,todo})[view]();
$$('[data-view]').forEach(b=>b.onclick=()=>{companySelected=null;if(b.dataset.view==='todo'){todoStage='list';todoTab='Tasks'}go(b.dataset.view)});$$('[data-command]').forEach(b=>b.onclick=()=>b.dataset.command==='wealth'?wealthBridge():rules());$$('[data-task]').forEach(b=>b.onclick=()=>{selectedTask=b.dataset.task;todoTab='Tasks';todoStage='draft';go('todo')});$$('[data-holding]').forEach(b=>b.onclick=()=>holdingDetail(b.dataset.holding));$$('[data-edit-holding]').forEach(b=>b.onclick=()=>holdingForm(b.dataset.editHolding));$$('[data-holding-tab]').forEach(b=>b.onclick=()=>{holdingTab=b.dataset.holdingTab;page=1;render()});$$('[data-cash-tab]').forEach(b=>b.onclick=()=>{cashTab=b.dataset.cashTab;render()});$$('[data-payment]').forEach(b=>b.onclick=()=>paymentDetail(b.dataset.payment));$$('[data-company]').forEach(b=>b.onclick=()=>{companySelected=b.dataset.company;render();window.scrollTo({top:0})});$$('[data-valuation]').forEach(b=>b.onclick=()=>valuationForm(b.dataset.valuation));$$('[data-price-company]').forEach(b=>b.onclick=()=>companyPriceForm(b.dataset.priceCompany));$$('[data-loan]').forEach(b=>b.onclick=()=>loanSchedule(b.dataset.loan));$$('[data-allowance]').forEach(b=>b.onclick=()=>allowanceDetail(b.dataset.allowance));$$('[data-option]').forEach(b=>b.onclick=()=>optionDetail(b.dataset.option));$$('[data-todo-tab]').forEach(b=>b.onclick=()=>{todoTab=b.dataset.todoTab;render()});$$('[data-select-task]').forEach(b=>b.onclick=()=>{if($('#draft-notes')){model.drafts[selectedTask]=$('#draft-notes').value;save()}selectedTask=b.dataset.selectTask;todoStage='draft';render();window.scrollTo({top:0})});$$('[data-evidence]').forEach(b=>b.onclick=()=>evidence(b.dataset.evidence));
if($('#schedule'))$('#schedule').onclick=scheduleForm;if($('#add-holding'))$('#add-holding').onclick=()=>holdingForm();if($('#export'))$('#export').onclick=exportHoldings;if($('#add-company'))$('#add-company').onclick=companyForm;if($('#add-option'))$('#add-option').onclick=optionForm;if($('#add-loan'))$('#add-loan').onclick=loanForm;if($('#tax-rules'))$('#tax-rules').onclick=rules;if($('#alltasks'))$('#alltasks').onclick=()=>{todoStage='list';go('todo')};if($('#allcompanies'))$('#allcompanies').onclick=()=>{companySelected=null;render();window.scrollTo({top:0})};
if(view==='holdings'){$('#owner-filter').onchange=e=>{ownerFilter=e.target.value;page=1;render()};$('#wrapper-filter').onchange=e=>{wrapperFilter=e.target.value;page=1;render()};$('#holding-mode').onchange=e=>{holdingMode=e.target.value;page=1;render()};$('#holding-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;page=1;render();$('#holding-search').focus();$('#holding-search').setSelectionRange(pos,pos)};$('#sortvalue').onclick=()=>{sortDesc=!sortDesc;page=1;render()};$('#prevpage').onclick=()=>{page--;render()};$('#nextpage').onclick=()=>{page++;render()}}
if(view==='capital'){$('#allocation').oninput=e=>{model.allocation=+e.target.value;save();$('#allocation-percent').textContent=model.allocation+'%';$('#capital-results').innerHTML=capitalResults()};$('#save-capital-plan').onclick=()=>{const amount=13000*model.allocation/100;if(!amount){toast('Set a repayment allocation above 0% first.');return}const payment={id:'capital-proposal',date:'2026-11-20',name:'Capital allocation proposal',from:'fic',to:'household',amount,type:'Loan repayment',status:'Proposed',note:'£14,000 illustrative receipts less £1,000 provisional tax cash reserve. Outstanding loans, liquidity and professional approval to check.'};const existing=model.payments.findIndex(p=>p.id===payment.id);if(existing>=0)model.payments[existing]=payment;else model.payments.push(payment);model.proposals.push({time:new Date().toISOString(),amount,allocation:model.allocation});save();toast('Repayment proposal saved to Cash flow. No payment made.')}}
if(view==='todo'&&todoTab==='Tasks'&&todoStage==='draft'){const f=filings.find(f=>f.id===selectedTask);$('#draft-notes').oninput=e=>{const text=e.target.value,pos=e.target.selectionStart;model.drafts[f.id]=text;const invalidate=['In professional review','Approved','Submitted (demo)'].includes(todoStatus(f));if(invalidate){model.filings[f.id]={...model.filings[f.id],status:'Ready to review'};model.audit.push({item:f.name,status:'Approval invalidated by draft edit',time:new Date().toISOString()})}save();if(invalidate){render();$('#draft-notes').focus();$('#draft-notes').setSelectionRange(pos,pos);toast('Draft changed. A fresh professional review is required.')}};$('#save-draft').onclick=()=>{model.drafts[f.id]=$('#draft-notes').value;save();toast('Draft changes saved locally.')};$('#download-draft').onclick=()=>download(`ILLUSTRATIVE DRAFT WORKPAPER — NOT FOR FILING\n${f.name}\n${f.entity}\n${f.period}\nDue: ${date(f.due)}\n\n${f.fields.map(([a,b])=>a+': '+b).join('\n')}\n\n${$('#draft-notes').value}`,'ron-'+f.id+'-draft.txt');if($('#sample-evidence'))$('#sample-evidence').onclick=()=>{model.filings[f.id]={...model.filings[f.id],evidenceReady:true,status:'Ready to review'};save();render();toast('Sample evidence attached for this demo.')};if($('#review-draft'))$('#review-draft').onclick=()=>taskTransition(f,'In professional review');if($('#attest')){const gate=()=>$('#approve-draft').disabled=!$('#attest').checked||!$('#reviewer').value.trim();$('#attest').onchange=gate;$('#reviewer').oninput=gate;$('#approve-draft').onclick=()=>taskTransition(f,'Approved',$('#reviewer').value.trim())}if($('#submit-attest')){$('#submit-attest').onchange=()=>$('#submit-draft').disabled=!$('#submit-attest').checked;$('#submit-draft').onclick=()=>taskTransition(f,'Submitted (demo)')}}}
$('.brand').onclick=e=>{e.preventDefault();companySelected=null;go('overview')};$('#modal .close').onclick=closeModal;$('#assumptions').onclick=rules;$('#reset').onclick=()=>{modal('<div class="modaleyebrow">DEMO WORKSPACE</div><h2>Reset your demo changes?</h2><p>Clear saved holdings edits, proposals and draft workflow changes in this browser.</p><div class="modalactions"><button data-close>Keep changes</button><button class="primary" id="confirm-reset">Reset demo</button></div>');bindModal();$('#confirm-reset').onclick=()=>{localStorage.removeItem('ron-office-v3');location.href=location.pathname+'#overview';location.reload()}};render();

function setAppearance(mode){const dark=mode==='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]').content=dark?'#111111':'#ffffff';$('#theme-toggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('#theme-toggle').setAttribute('aria-pressed',String(dark));$('#theme-label').textContent=dark?'Light mode':'Dark mode'}
setAppearance(document.documentElement.dataset.theme||'light');
$('#theme-toggle').onclick=()=>{const mode=document.documentElement.dataset.theme==='dark'?'light':'dark';setAppearance(mode);try{localStorage.setItem('ron-appearance',mode)}catch{toast('Appearance changed for this visit.')}};
